import { PERSONAL_STATUSES,validatePersonal } from './personal.js';
import { today,displayDate,parseDisplayDate,staffLabel } from './engine.js';

export function createProductivity(hooks) {
  const {escape,modal,toast,render,api,reload,getData,getUser,getMode,getView,dateField,storageKey}=hooks;
  const $=selector=>document.querySelector(selector);
  let personalFilter='open',search='',sort='priority',period='day',rankState=null,pendingKey=null;
  const ownTasks=()=> (getData().personalTasks||[]).filter(t=>getMode()==='live'||t.userId===getUser().id);
  const rankKey=()=>`${getMode()}:${getUser()?.id||''}:${period}:${today()}:${getData()?.activity?.[0]?.id||''}`;
  const overdue=t=>t.status!=='done'&&t.dueDate&&t.dueDate<today();
  function personalPanel() {
    const all=ownTasks(),open=all.filter(t=>t.status!=='done');
    const list=all.filter(t=>(personalFilter==='all'||personalFilter==='open'&&t.status!=='done'||personalFilter==='overdue'&&overdue(t)||personalFilter===t.status)&&`${t.title} ${t.notes} ${t.subtasks.map(s=>s.title).join(' ')}`.toLowerCase().includes(search.toLowerCase()));
    const weights={urgent:0,high:1,normal:2};
    list.sort((a,b)=>sort==='date'?(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||a.title.localeCompare(b.title):sort==='newest'?b.updatedAt.localeCompare(a.updatedAt):weights[a.priority]-weights[b.priority]||(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||a.title.localeCompare(b.title));
    return `<div class="personal-summary"><span class="badge neutral">${open.length} open</span><span class="badge danger">${all.filter(overdue).length} overdue</span><span class="badge">${all.length-open.length} completed</span><p>Your list is private to your account. Personal tasks do not affect employee ranks.</p></div><section class="panel personal-panel"><div class="panel-head"><div><h2>Your to-do list</h2><p>Plan your day, break tasks into steps, and keep your own notes.</p></div><button class="btn" data-personal-action="new">+ New personal task</button></div><div class="personal-toolbar"><div class="filters" aria-label="Personal task filters">${[['open','Open'],['all','All'],['in_progress','In progress'],['overdue','Overdue'],['done','Completed']].map(([value,label])=>`<button data-personal-filter="${value}" class="${personalFilter===value?'active':''}" aria-pressed="${personalFilter===value}">${label}</button>`).join('')}</div><div class="personal-search"><label for="personal-search">Search your tasks</label><input id="personal-search" type="search" placeholder="Search title, notes, or steps…" value="${escape(search)}"></div><div><label for="personal-sort">Sort by</label><select id="personal-sort">${[['priority','Priority'],['date','Due date'],['newest','Recently updated']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="personal-list">${list.map(t=>`<article class="personal-task ${t.status==='done'?'personal-done':''} ${overdue(t)?'personal-overdue':''}"><div class="personal-task-head"><label class="personal-complete"><input type="checkbox" data-personal-complete="${escape(t.id)}" ${t.status==='done'?'checked':''} aria-label="${t.status==='done'?'Reopen':'Complete'} ${escape(t.title)}"><span>${escape(t.title)}</span></label><span class="badge ${t.priority==='urgent'?'danger':t.priority==='high'?'warn':'neutral'}">${escape(t.priority[0].toUpperCase()+t.priority.slice(1))} priority</span></div><div class="personal-task-meta"><span class="badge">${PERSONAL_STATUSES[t.status]}</span>${t.dueDate?`<span class="${overdue(t)?'overdue-date':''}">${overdue(t)?'Overdue · ':t.dueDate===today()?'Due today · ':'Due '}${displayDate(t.dueDate)}</span>`:'<span>No due date</span>'}${t.subtasks.length?`<span>${t.subtasks.filter(s=>s.done).length}/${t.subtasks.length} steps complete</span>`:''}</div>${t.notes?`<p class="personal-notes">${escape(t.notes)}</p>`:''}${t.subtasks.length?`<ul class="personal-subtasks">${t.subtasks.map((s,i)=>`<li><label><input type="checkbox" data-personal-step="${escape(t.id)}" data-index="${i}" ${s.done?'checked':''}><span class="${s.done?'done':''}">${escape(s.title)}</span></label></li>`).join('')}</ul>`:''}<div class="personal-task-actions"><button class="text-btn" data-personal-action="edit" data-id="${escape(t.id)}">Edit task</button>${t.status==='todo'?`<button class="text-btn" data-personal-action="start" data-id="${escape(t.id)}">Start task</button>`:''}<button class="text-btn personal-delete" data-personal-action="delete" data-id="${escape(t.id)}">Delete</button></div></article>`).join('')||`<div class="empty"><h3>${all.length?'No matching tasks.':'A little space for your own plans.'}</h3><p>${all.length?'Try another filter or search.':'Create your first personal task to get started.'}</p></div>`}</div></section>`;
  }
  async function savePersonal(input,id,remove=false) {
    const existing=ownTasks().find(t=>t.id===id);
    if(getMode()==='live') {
      await api(`personal-tasks${id?'/'+encodeURIComponent(id):''}`,{method:remove?'DELETE':id?'PATCH':'POST',body:JSON.stringify({...input,...(id?{_version:existing.version}:{})})});
      await reload();
    }else {
      const data=getData();data.personalTasks??=[];
      if(remove)data.personalTasks=data.personalTasks.filter(t=>t.id!==id||t.userId!==getUser().id);
      else {const task={...validatePersonal(input,existing),id:id||crypto.randomUUID(),userId:getUser().id,updatedAt:new Date().toISOString()};if(id)data.personalTasks=data.personalTasks.map(t=>t.id===id?task:t);else data.personalTasks.push(task);}
      localStorage.setItem(storageKey,JSON.stringify(data));
    }
    render();
  }
  function personalForm(id) {
    const task=id?ownTasks().find(t=>t.id===id):{};if(!task)return;
    modal(id?'Edit personal task':'New personal task','Private to you. Build a clear plan at your own pace.',`<form id="personal-form"><div class="fields"><div class="field full"><label for="personal-title">Task title</label><input id="personal-title" name="title" maxlength="160" value="${escape(task.title||'')}" placeholder="What would you like to do?" required></div>${dateField('Due date (optional)','dueDate',task.dueDate||'','','personal-due',false)}<div class="field"><label for="personal-priority">Priority</label><select id="personal-priority" name="priority">${['normal','high','urgent'].map(v=>`<option value="${v}" ${(task.priority||'normal')===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="field full"><label for="personal-status">Status</label><select id="personal-status" name="status">${Object.entries(PERSONAL_STATUSES).map(([v,l])=>`<option value="${v}" ${(task.status||'todo')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="personal-notes">Notes (optional)</label><textarea id="personal-notes" name="notes" maxlength="3000" placeholder="Details, ideas, or anything you need to remember…">${escape(task.notes||'')}</textarea></div><div class="field full"><label for="personal-steps">Steps (optional)</label><textarea id="personal-steps" name="steps" maxlength="3220" rows="5" placeholder="One step per line">${escape((task.subtasks||[]).map(s=>s.title).join('\n'))}</textarea><small>One step per line, up to 20 steps. Check them off from your task list.</small></div></div><div class="error" id="personal-error" role="alert"></div></form>`,`<button class="btn secondary" data-close>Cancel</button><button class="btn" form="personal-form">${id?'Save changes':'Create personal task'}</button>`);
    $('#personal-form').onsubmit=async event=>{event.preventDefault();const b=$('[form="personal-form"]');b.disabled=true;try{const input=Object.fromEntries(new FormData(event.target));input.dueDate=input.dueDate?parseDisplayDate(input.dueDate):'';input.subtasks=input.steps.split(/\r?\n/).filter(s=>s.trim()).map(title=>({title,done:!!task.subtasks?.find(s=>s.title===title.trim())?.done}));delete input.steps;validatePersonal(input);await savePersonal(input,id);$('#modal').close();toast(id?'Personal task updated.':'Personal task created.');}catch(error){$('#personal-error').textContent=error.message;b.disabled=false;}};
  }
  function deletePersonal(id) {
    const t=ownTasks().find(t=>t.id===id);if(!t)return;
    modal('Delete personal task',t.title,'<p>This removes the task and its steps from your personal list.</p><div class="error" id="personal-delete-error" role="alert"></div>','<button class="btn secondary" data-close>Cancel</button><button class="btn" id="personal-delete-confirm">Delete task</button>');
    $('#personal-delete-confirm').onclick=async event=>{event.target.disabled=true;try{await savePersonal({},id,true);$('#modal').close();toast('Personal task deleted.');}catch(error){$('#personal-delete-error').textContent=error.message;event.target.disabled=false;}};
  }
  function rankPanel() {
    const state=rankState?.key===rankKey()?rankState:null,rows=state?.data?.rows||[],leader=rows.find(r=>r.score>0);
    return `<section class="panel rank-panel"><div class="panel-head"><div><h2>Employee leaderboard</h2><p>${state?.data?`${displayDate(state.data.start)} — ${displayDate(state.data.end)} · Cairo time`:'Daily and weekly results from recorded work.'}</p></div><button class="btn secondary" id="rank-refresh">Refresh</button></div><div class="rank-controls filters" aria-label="Ranking period">${[['day','Today'],['week','This week']].map(([v,l])=>`<button data-rank-period="${v}" class="${period===v?'active':''}" aria-pressed="${period===v}">${l}</button>`).join('')}</div>${getMode()==='demo'?'<div class="notice">Employee ranks are available after signing in to the company workspace.</div>':!state?'<div class="empty" role="status">Loading employee results…</div>':state.error?`<div class="empty" role="alert"><h3>Results could not be loaded.</h3><p>${escape(state.error)}</p><button class="btn secondary" id="rank-retry">Try again</button></div>`:`${leader?`<div class="rank-leader"><span class="eyebrow">Best employee ${period==='day'?'today':'this week'}</span><h3>${escape(rows.filter(r=>r.score===leader.score).map(r=>r.name).join(' & '))}</h3><p>${leader.score} points · ${leader.activeDays} active workday${leader.activeDays===1?'':'s'}</p></div>`:'<div class="empty"><h3>No scored work yet.</h3><p>Results appear as employees complete client work and shared tasks.</p></div>'}<ol class="rank-list">${rows.map(r=>`<li class="rank-row ${r.id===getUser().id?'rank-you':''}"><span class="rank-number" aria-label="${r.position?'Rank '+r.position:'Unranked'}">${r.position||'—'}</span><div class="rank-person"><h3>${escape(r.name)} ${r.id===getUser().id?'<span class="badge">You</span>':''}</h3><p>${escape(staffLabel({role:'employee',staffType:r.staffType}))} · ${r.activeDays} active workday${r.activeDays===1?'':'s'}</p><div class="rank-breakdown"><span>${r.completedSteps} checklist steps</span><span>${r.followups} follow-ups</span><span>${r.tasksCompleted} shared tasks</span><span>${r.filesCreated} files created</span><span>${r.handoffs} handoffs</span></div></div><strong class="rank-score">${r.score}<small>points</small></strong></li>`).join('')}</ol>`}</section><section class="panel rank-rules"><h2>How points work</h2><div class="rank-point-grid"><p><strong>5 points</strong>Completed checklist step</p><p><strong>5 points</strong>Client follow-up, once per client per day</p><p><strong>3 points</strong>Completed shared task or consultation handoff</p><p><strong>1 point</strong>New client case or consultation</p><p><strong>+1 point</strong>Each day with scored work</p></div><p>Only active employees are ranked. Personal tasks stay private and earn no points. Repeating a completion does not earn extra credit; reopened steps stop counting until completed again. Daily shared tasks can earn credit once each day. Edits, page visits, and refreshes earn no points. The week starts on Monday in Cairo.</p></section>`;
  }
  async function loadRank(force=false) {
    if(getMode()!=='live')return;
    const key=rankKey();if(pendingKey===key||!force&&rankState?.key===key)return;
    pendingKey=key;rankState=null;
    try{const data=await api('rank?period='+period);if(rankKey()===key)rankState={key,data};}
    catch(error){if(rankKey()===key)rankState={key,error:error.message};}
    finally{if(pendingKey===key)pendingKey=null;if(getUser()&&getView()==='rank'&&rankKey()===key)render();}
  }
  function bind() {
    document.querySelectorAll('[data-personal-action]').forEach(b=>b.onclick=()=>{const {personalAction:action,id}=b.dataset;if(action==='new'||action==='edit')personalForm(id);else if(action==='delete')deletePersonal(id);else if(action==='start')runChange(b,()=>savePersonal({status:'in_progress'},id));});
    document.querySelectorAll('[data-personal-filter]').forEach(b=>b.onclick=()=>{personalFilter=b.dataset.personalFilter;render();});
    $('#personal-sort')?.addEventListener('change',event=>{sort=event.target.value;render();});
    $('#personal-search')?.addEventListener('input',event=>{search=event.target.value;const position=event.target.selectionStart;render();$('#personal-search').focus();$('#personal-search').setSelectionRange(position,position);});
    document.querySelectorAll('[data-personal-complete]').forEach(b=>b.onchange=()=>runChange(b,()=>savePersonal({status:b.checked?'done':'todo'},b.dataset.personalComplete)));
    document.querySelectorAll('[data-personal-step]').forEach(b=>b.onchange=()=>{const t=ownTasks().find(t=>t.id===b.dataset.personalStep);runChange(b,()=>savePersonal({subtasks:t.subtasks.map((s,i)=>i===Number(b.dataset.index)?{...s,done:b.checked}:s)},t.id));});
    document.querySelectorAll('[data-rank-period]').forEach(b=>b.onclick=()=>{period=b.dataset.rankPeriod;rankState=null;render();});
    for(const id of ['rank-refresh','rank-retry'])$( '#'+id)?.addEventListener('click',()=>{rankState=null;loadRank(true);render();});
    if(getView()==='rank')loadRank();
  }
  async function runChange(button,callback) {button.disabled=true;try{await callback();}catch(error){render();toast(error.message);}}
  return {personalPanel,rankPanel,bind};
}
